import{_ as o,o as t,c,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Sequence Flow — Delete Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-15-delete-workspace/sequence-flow.md","filePath":"feature/agency-workspace/3-4-15-delete-workspace/sequence-flow.md"}'),a={name:"feature/agency-workspace/3-4-15-delete-workspace/sequence-flow.md"};function d(s,e,l,i,n,p){return t(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-delete-workspace" tabindex="-1">Sequence Flow — Delete Workspace <a class="header-anchor" href="#sequence-flow-—-delete-workspace" aria-label="Permalink to &quot;Sequence Flow — Delete Workspace&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.15). Reflects the implemented code &gt; (<code>WorkspaceController</code>, <code>WorkspaceServiceImpl</code>, <code>AgencyRepository</code>, &gt; <code>WorkspaceRepository</code>) and the real FE (<code>detail.tsx</code> danger zone). &gt; &gt; Updated: 2026-09-25.</p><h2 id="actors-lifelines" tabindex="-1">Actors / Lifelines <a class="header-anchor" href="#actors-lifelines" aria-label="Permalink to &quot;Actors / Lifelines&quot;">​</a></h2><ul><li><strong>Owner</strong> — the Agency owner, acting from the Workspace settings danger zone (<code>detail.tsx</code>).</li><li><strong>WorkspaceController</strong> — <code>deleteWorkspace</code> / <code>restoreWorkspace</code> endpoints.</li><li><strong>WorkspaceServiceImpl</strong> — <code>deleteWorkspace</code> / <code>restoreWorkspace</code> business logic.</li><li><strong>AgencyRepository</strong> — resolves the parent Agency to check ownership.</li><li><strong>WorkspaceRepository</strong> — loads/saves the Workspace row.</li></ul><p>⚠ There is no FE actor for Restore — the flow below documents the backend capability only; no screen currently triggers it.</p><hr><h2 id="flow-a-—-delete-workspace" tabindex="-1">Flow A — Delete Workspace <a class="header-anchor" href="#flow-a-—-delete-workspace" aria-label="Permalink to &quot;Flow A — Delete Workspace&quot;">​</a></h2><ol><li>Owner → WorkspaceController: types the Workspace name to confirm in the danger-zone dialog, then <code>DELETE /api/v1/workspaces/{workspaceId}</code>.</li><li>WorkspaceController → WorkspaceServiceImpl: <code>deleteWorkspace(workspaceId, currentUser)</code>.</li><li>WorkspaceServiceImpl → WorkspaceRepository: <code>findWorkspaceOrThrow(workspaceId)</code>; missing → 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>WorkspaceServiceImpl → AgencyRepository: <code>findById(workspace.getAgencyId())</code>; missing → 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>WorkspaceServiceImpl: compares <code>agency.getOwnerId()</code> to <code>currentUser.getId()</code>; mismatch → 403 <code>FORBIDDEN</code>.</li><li>WorkspaceServiceImpl: sets <code>status = SOFT_DELETED</code>, <code>deletedAt = now()</code>, <code>updatedAt = now()</code>.</li><li>WorkspaceServiceImpl → WorkspaceRepository: <code>save(workspace)</code>.</li><li>WorkspaceController → Owner: 200 <code>ApiResponse.ok(null)</code>.</li><li>Owner (FE): success toast, navigate to <code>/workspace</code>.</li></ol><h2 id="flow-b-—-restore-workspace-backend-capability-no-fe-trigger-today" tabindex="-1">Flow B — Restore Workspace (backend capability; no FE trigger today) <a class="header-anchor" href="#flow-b-—-restore-workspace-backend-capability-no-fe-trigger-today" aria-label="Permalink to &quot;Flow B — Restore Workspace (backend capability; no FE trigger today)&quot;">​</a></h2><ol><li>Caller → WorkspaceController: <code>POST /api/v1/workspaces/{workspaceId}/restore</code>.</li><li>WorkspaceController → WorkspaceServiceImpl: <code>restoreWorkspace(workspaceId, currentUser)</code>.</li><li>WorkspaceServiceImpl → WorkspaceRepository: <code>findWorkspaceOrThrow(workspaceId)</code>; missing → 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>WorkspaceServiceImpl → AgencyRepository: <code>findById(workspace.getAgencyId())</code>; missing → 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>WorkspaceServiceImpl: compares <code>agency.getOwnerId()</code> to <code>currentUser.getId()</code>; mismatch → 403 <code>FORBIDDEN</code>.</li><li>WorkspaceServiceImpl: checks <code>workspace.getStatus() == SOFT_DELETED</code>; otherwise → 400 <code>WORKSPACE_NOT_DELETED</code>.</li><li>WorkspaceServiceImpl: checks <code>deletedAt != null &amp;&amp; now().isBefore(deletedAt.plusDays(30))</code>; otherwise → 410 <code>RESTORE_WINDOW_EXPIRED</code>.</li><li>WorkspaceServiceImpl: sets <code>status = ACTIVE</code>, <code>deletedAt = null</code>, <code>updatedAt = now()</code>.</li><li>WorkspaceServiceImpl → WorkspaceRepository: <code>save(workspace)</code> → returns <code>WorkspaceResponse</code>.</li><li>WorkspaceController → Caller: 200 with the restored <code>WorkspaceResponse</code>.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Delete/Restore</td><td>Workspace does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>Delete/Restore</td><td>Caller is not the Agency OWNER (⚠ role gate not formally confirmed)</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Restore</td><td>Workspace status is not <code>SOFT_DELETED</code></td><td>400</td><td><code>WORKSPACE_NOT_DELETED</code></td></tr><tr><td>Restore</td><td>More than 30 days since <code>deletedAt</code></td><td>410</td><td><code>RESTORE_WINDOW_EXPIRED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The role gate is implemented against Agency <code>ownerId</code>, not via <code>@RequireRole</code> (that annotation only understands WorkspaceMember roles) — see the code comment in <code>WorkspaceServiceImpl</code> citing the <code>AgencyServiceImpl.removeAgency</code> precedent.</li><li>⚠ Cascade effects on Task/Campaign/Material data described in <code>spec.md</code>&#39;s Business Rules are not performed inside <code>deleteWorkspace</code> itself — flagged there as an open BA conflict, not modeled as steps here since they are not confirmed to exist in code.</li><li>No FE screen currently calls the restore endpoint; Flow B is backend-only today.</li></ul>',15)])])}const g=o(a,[["render",d]]);export{h as __pageData,g as default};
